  function resolveLocale(requested, navigatorLike) {
    if (SUPPORTED.includes(requested)) return requested;
    const candidates = (navigatorLike && (navigatorLike.languages || [navigatorLike.language])) || [];
    return candidates.some((value) => /^zh(?:-|$)/i.test(value || "")) ? "zh-CN" : "en";
  }

